import{flattenedDecrypt}from"../flattened/decrypt.js";import{JWEDecryptionFailed,JWEInvalid}from"../../util/errors.js";import{isObject}from"../../lib/type_checks.js";export async function generalDecrypt(e,t,r){if(!isObject(e))throw new JWEInvalid("General JWE must be an object");if(!Array.isArray(e.recipients)||!e.recipients.every(isObject))throw new JWEInvalid("JWE Recipients missing or incorrect type");if(!e.recipients.length)throw new JWEInvalid("JWE Recipients has no members");for(const i of e.recipients)try{return await flattenedDecrypt({aad:e.aad,ciphertext:e.ciphertext,encrypted_key:i.encrypted_key,header:i.header,iv:e.iv,protected:e.protected,tag:e.tag,unprotected:e.unprotected},t,r)}catch{}throw new JWEDecryptionFailed}